package com._8x8.herd.device_logs.upload.upload;

import com._8x8.herd.device_logs.contract.LogFileName;
import com._8x8.herd.device_logs.contract.ObjectKey;
import com._8x8.herd.device_logs.upload.policy.PolicyDecision;
import com._8x8.herd.device_logs.upload.policy.Rejection;
import com._8x8.herd.device_logs.upload.policy.UploadPolicy;
import com._8x8.herd.device_logs.upload.storage.LogObject;
import com._8x8.herd.device_logs.upload.storage.LogStorage;
import com._8x8.herd.device_logs.upload.storage.LogStorageException;
import com._8x8.herd.device_logs.upload.storage.StoreResult;
import com._8x8.herd.device_logs.upload.trust.ClientIdentity;

import java.io.IOException;
import java.io.InputStream;
import java.net.SocketTimeoutException;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Optional;
import java.util.OptionalLong;

import org.springframework.http.HttpHeaders;
import org.springframework.stereotype.Component;

/**
 * Runs one upload end to end: the header checks, then the key from the UTC receive time, then the create-only write.
 * Expected failures come back as an outcome, never as an exception, so every path is answered and logged alike.
 */
@Component
public class UploadFlow {

    private final UploadPolicy policy;
    private final LogStorage storage;
    private final Clock clock;

    public UploadFlow(UploadPolicy policy, LogStorage storage, Clock clock) {
        this.policy = policy;
        this.storage = storage;
        this.clock = clock;
    }

    /**
     * @param fileName the path after /logs/, exactly as uploaded
     * @param headers the request headers
     * @param contentLength the request Content-Length, empty if it has none
     * @param body opened only once every check has passed
     */
    public UploadOutcome upload(String fileName, HttpHeaders headers, OptionalLong contentLength, Body body) {
        Instant receivedAt = clock.instant();
        PolicyDecision decision = policy.check(fileName, headers, contentLength);
        if (decision instanceof PolicyDecision.Rejected rejected) {
            return new UploadOutcome.Rejected(rejected.reason(), rejected.file(), rejected.identity(), Optional.empty(),
                    contentLength, Optional.empty(), since(receivedAt));
        }
        PolicyDecision.Allowed allowed = (PolicyDecision.Allowed) decision;
        LogFileName file = allowed.file();
        ClientIdentity identity = allowed.identity();
        ObjectKey key = new ObjectKey(file.mac(), receivedAt, file.type());
        LogObject object = new LogObject(key, allowed.contentLength(),
                Optional.ofNullable(headers.getFirst(HttpHeaders.USER_AGENT)), identity.sourceIp(),
                identity.certSerial(), file.manual(), file.name());

        TrackedBody tracked;
        try {
            tracked = new TrackedBody(body.open());
        } catch (IOException e) {
            return rejected(bodyRejection(e), allowed, key, Optional.of(e), receivedAt);
        }
        StoreResult result;
        try {
            result = storage.store(object, tracked);
        } catch (LogStorageException e) {
            // Storage reports the failure as its own, but when the body's read failed first, the phone is the problem,
            // not S3, and Tomcat has already answered it with 400 or 408.
            Optional<IOException> readFailure = tracked.failure();
            if (readFailure.isPresent()) {
                return rejected(bodyRejection(readFailure.get()), allowed, key, Optional.of(readFailure.get()),
                        receivedAt);
            }
            return rejected(Rejection.STORAGE_FAILED, allowed, key, Optional.of(e), receivedAt);
        }
        if (result == StoreResult.KEY_EXISTS) {
            return rejected(Rejection.KEY_EXISTS, allowed, key, Optional.empty(), receivedAt);
        }
        return new UploadOutcome.Stored(key, identity, allowed.contentLength(), since(receivedAt));
    }

    // The same test Tomcat makes in InputBuffer.handleReadException, so the reason matches the code it sent. Tomcat
    // wraps the read failure in its ClientAbortException, so the timeout can be a cause rather than the exception.
    private static Rejection bodyRejection(IOException failure) {
        for (Throwable cause = failure; cause != null; cause = cause.getCause()) {
            if (cause instanceof SocketTimeoutException) {
                return Rejection.BODY_TIMEOUT;
            }
        }
        return Rejection.BODY_INCOMPLETE;
    }

    private UploadOutcome.Rejected rejected(Rejection reason, PolicyDecision.Allowed allowed, ObjectKey key,
                                            Optional<Exception> cause, Instant receivedAt) {
        return new UploadOutcome.Rejected(reason, Optional.of(allowed.file()), Optional.of(allowed.identity()),
                Optional.of(key), OptionalLong.of(allowed.contentLength()), cause, since(receivedAt));
    }

    private Duration since(Instant receivedAt) {
        return Duration.between(receivedAt, clock.instant());
    }

    /**
     * The request body, opened only after every check passes. Tomcat sends 100 Continue on the first read, and the
     * phone then sends the whole file.
     */
    @FunctionalInterface
    public interface Body {

        InputStream open() throws IOException;
    }
}

